@Serializable(with = ScheduleSpecSerializer::class)
sealed interface ScheduleSpec { val `kind`: String }

/** A ScheduleSpec variant this build does not know, kept as it came. */
data class UnknownScheduleSpec(override val raw: JsonObject) : ScheduleSpec, UnknownVariant {
    override val `kind`: String get() = raw["kind"]?.jsonPrimitive?.contentOrNull.orEmpty()
}

object ScheduleSpecSerializer : UnionSerializer<ScheduleSpec>("ScheduleSpec", "kind", mapOf(
    "interval" to ScheduleSpecInterval.serializer(),
    "daily" to ScheduleSpecDaily.serializer(),
    "weekly" to ScheduleSpecWeekly.serializer(),
    "cron" to ScheduleSpecCron.serializer(),
    "github-review-requested" to ScheduleSpecGithubReviewRequested.serializer(),
), { it.`kind` }, ::UnknownScheduleSpec)

