data class UnknownEvent(val raw: JsonObject) : ProtocolEvent

fun decodeProtocolEvent(raw: JsonObject, json: Json): ProtocolEvent = when(raw["type"]?.jsonPrimitive?.content) {
    "auth.devicesChanged" -> json.decodeFromJsonElement(AuthDevicesChangedEvent.serializer(), raw)
    "auth.pairingRequested" -> json.decodeFromJsonElement(AuthPairingRequestedEvent.serializer(), raw)
    "auth.sessionRevoked" -> json.decodeFromJsonElement(AuthSessionRevokedEvent.serializer(), raw)
    "project.state" -> json.decodeFromJsonElement(ProjectStateEvent.serializer(), raw)
    "credentials.login" -> json.decodeFromJsonElement(CredentialsLoginEvent.serializer(), raw)
    "conversation.view" -> json.decodeFromJsonElement(ConversationViewEvent.serializer(), raw)
    "conversation.watchEnded" -> json.decodeFromJsonElement(ConversationWatchEndedEvent.serializer(), raw)
    "workers.state" -> json.decodeFromJsonElement(WorkersStateEvent.serializer(), raw)
    "artifacts.changed" -> json.decodeFromJsonElement(ArtifactsChangedEvent.serializer(), raw)
    "terminal.closed" -> json.decodeFromJsonElement(TerminalClosedEvent.serializer(), raw)
    "terminal.resync" -> json.decodeFromJsonElement(TerminalResyncEvent.serializer(), raw)
    "drafts.changed" -> json.decodeFromJsonElement(DraftsChangedEvent.serializer(), raw)
    "threads.state" -> json.decodeFromJsonElement(ThreadsStateEvent.serializer(), raw)
    "subscriptions.usage.changed" -> json.decodeFromJsonElement(SubscriptionsUsageEvent.serializer(), raw)
    "board.state" -> json.decodeFromJsonElement(BoardStateEvent.serializer(), raw)
    "schedules.state" -> json.decodeFromJsonElement(SchedulesStateEvent.serializer(), raw)
    "conversation.context.changed" -> json.decodeFromJsonElement(ConversationContextEvent.serializer(), raw)
    "server.status.changed" -> json.decodeFromJsonElement(ServerStatusEvent.serializer(), raw)
    "memory.changed" -> json.decodeFromJsonElement(MemoryChangedEvent.serializer(), raw)
    else -> UnknownEvent(raw)
}
